def _merge_json_audio_metadata(metadata: Dict[str, Any]) -> Dict[str, Any]:
    """Apply Rasa JSON audio WebSocket settings onto agent metadata."""
    merged = dict(metadata)
    for key, value in _RASA_JSON_AUDIO_METADATA.items():
        if key == "custom_headers":
            headers = dict(merged.get("custom_headers") or {})
            headers.update(value)
            merged["custom_headers"] = headers
        else:
            merged[key] = value
    return merged


def _build_endpoint_patch_payload(
    agent: Dict[str, Any],
    endpoint_url: str,
    *,
    rasa_sender_id: Optional[str] = None,
    rasa_sender_header: str = DEFAULT_RASA_SENDER_HEADER,
) -> Dict[str, Any]:
    """Build a PATCH body that sets the dial target for the agent model type."""
    model_type = str(agent.get("model_type", ""))
    if model_type == "MODEL_TYPE_OUTBOUND_VOICE":
        metadata = dict(agent.get("metadata") or {})
        headers = dict(metadata.get("trigger_call_headers") or {})
        headers[rasa_sender_header] = (
            rasa_sender_id
            if rasa_sender_id is not None
            else RASA_SENDER_ID_HEADER_TEMPLATE
        )
        metadata["trigger_call_headers"] = headers
        return {
            "endpoint": endpoint_url,
            "metric_ids": list(_RASA_CI_HYBRID_METRIC_IDS),
            "metadata": metadata,
        }

    metadata = dict(agent.get("metadata") or {})
    metadata["endpoint"] = endpoint_url
    if model_type in ("MODEL_TYPE_WEBSOCKET", "MODEL_TYPE_CHAT_WEBSOCKET", ""):
        metadata = _merge_json_audio_metadata(metadata)
    headers = dict(metadata.get("custom_headers") or {})
    headers[rasa_sender_header] = (
        rasa_sender_id if rasa_sender_id is not None else RASA_SENDER_ID_HEADER_TEMPLATE
    )
    metadata["custom_headers"] = headers
    return {
        "metadata": metadata,
        "metric_ids": list(_RASA_CI_HYBRID_METRIC_IDS),
    }


def build_json_audio_agent_create_payload(
    display_name: str = "json audio",
    *,
    endpoint_url: str = "",
) -> Dict[str, Any]:
    """Build a POST body for a Rasa JSON audio WebSocket Coval agent."""
    metadata = _merge_json_audio_metadata({"connection_mode": "direct"})
    metadata["endpoint"] = endpoint_url or _PLACEHOLDER_JSON_AUDIO_WSS
    return {
        "display_name": display_name,
        "model_type": "MODEL_TYPE_WEBSOCKET",
        "metadata": metadata,
        "metric_ids": list(_RASA_CI_HYBRID_METRIC_IDS),
    }


async def create_json_audio_agent(
    client: CovalClient,
    display_name: str = "json audio",
    *,
    endpoint_url: str = "",
) -> str:
    """Create a generic Coval JSON audio agent and return its id."""
    payload = build_json_audio_agent_create_payload(
        display_name,
        endpoint_url=endpoint_url,
    )
    return await client.create_agent(payload)


async def update_agent_endpoint(
    client: CovalClient,
    agent_id: str,
    endpoint_url: str,
    *,
    rasa_sender_id: Optional[str] = None,
    rasa_sender_header: str = DEFAULT_RASA_SENDER_HEADER,
    display_name: Optional[str] = None,
) -> None:
    """PATCH a Coval agent so voice simulations target ``endpoint_url``.

    For Rasa's JSON audio WebSocket channel, Coval expects the WebSocket URL in
    ``metadata.endpoint`` plus typed JSON audio framing at 16 kHz. Also applies
    CI hybrid ``metric_ids`` so simulations score the same Coval metrics as GHA.

    For WebSocket agents, ``metadata.custom_headers[rasa_sender_header]`` defaults
    to ``{{run_metadata.rasa_sender_id}}`` so Coval resolves a per-launch sender
    from launch metadata. Outbound voice uses the same template in
    ``metadata.trigger_call_headers``. Pass ``rasa_sender_id`` only to override
    with a concrete id (legacy SIP/tests).
    """
    agent = await client.get_agent(agent_id)
    payload = _build_endpoint_patch_payload(
        agent,
        endpoint_url,
        rasa_sender_id=rasa_sender_id,
        rasa_sender_header=rasa_sender_header,
    )
    if display_name:
        payload["display_name"] = display_name
    await client._request("PATCH", f"agents/{agent_id}", json_body=payload)
